#!/bin/bash
set -e
mkdir -p /opt/projects/digest
base64 -d > /opt/projects/digest/digest.py <<'B64EOF'

B64EOF
cp -f /opt/hermes-chat-agent/config.json /opt/projects/digest/config.json
chmod 600 /opt/projects/digest/config.json
echo "=== ТЕСТ ОТЧЁТА ==="
set -a; . /etc/default/hermes-chat-agent; set +a
/usr/bin/python3 /opt/projects/digest/digest.py
echo "=== ГОТОВО ==="
